export function communityT(lang: AppLanguage, key: CommunityMessageKey, vars?: Record<string, string | number>): string {
  const raw = COMMUNITY_MESSAGES[lang]?.[key] ?? COMMUNITY_MESSAGES.en[key] ?? key;
  if (!vars) return raw;
  return Object.entries(vars).reduce(
    (s, [k, v]) => s.split('{' + k + '}').join(String(v)),
    raw,
  );
}
